def generate_and_validate(root_dir: str):
    targets = [
        os.path.join(root_dir, "Potaria_Projectile_Asset_Library.json"),
        os.path.join(root_dir, "docs", "Potaria_Projectile_Asset_Library.json")
    ]
    
    for path in targets:
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "w", encoding="utf-8") as f:
            json.dump(data, f, ensure_ascii=False, indent=2)

        with open(path, "r", encoding="utf-8") as f:
            checked = json.load(f)
        assert len(checked["projectiles"]) == 40
        assert [p["id"] for p in checked["projectiles"]] == [f"P{i:02d}" for i in range(1, 41)]
        print(f"Created and validated {path}")
        print(f"Projectiles: {len(checked['projectiles'])}")
        print(f"File size: {os.path.getsize(path):,} bytes")

if __name__ == "__main__":
    script_dir = os.path.dirname(os.path.abspath(__file__))
    workspace_root = os.path.abspath(os.path.join(script_dir, ".."))
    generate_and_validate(workspace_root)
